"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   BLOG_POSTS: () => (/* binding */ BLOG_POSTS)\n/* harmony export */ });\nconst BLOG_POSTS = [\n    {\n        slug: \"marathi-marriage-biodata-format-guide\",\n        title: \"How to Create a Perfect Marathi Marriage Biodata: Complete 2026 Guide\",\n        marathiTitle: \"मराठी विवाह बायोडाटा कसा तयार करावा? सविस्तर मार्गदर्शक\",\n        excerpt: \"Learn what to include, how to respectfully write family details, and the right format for horoscope matching in traditional Maharashtrian families.\",\n        category: \"Marathi\",\n        date: \"2026-08-20\",\n        readTime: \"6 min read\",\n        author: \"विवाहपत्रिका संपादकीय मंडळ\",\n        coverGradient: \"linear-gradient(135deg, #722F37 0%, #A8321D 100%)\",\n        tags: [\n            \"मराठी बायोडाटा\",\n            \"पारंपारिक\",\n            \"लग्न पत्रिका\",\n            \"Family Details\"\n        ],\n        content: [\n            \"विवाह हा दोन व्यक्तींबरोबरच दोन कुटुंबांचा पवित्र संगम असतो. भारतीय संस्कृतीत आणि विशेषतः महाराष्ट्रीयन परंपरेत लग्नाचे स्थळ शोधताना सर्वात पहिले पाहिली जाते ती म्हणजे 'बायोडाटा' (विवाह पत्रिका). पहिल्याच भेटीत किंवा संभाषणात तुमचा बायोडाटा ही तुमची पहिली छाप असते.\",\n            \"बायोडाटा तयार करताना प्रामुख्याने चार ते पाच प्रमुख विभाग असतात: वैयक्तिक माहिती (Personal Details), शिक्षण व नोकरी/व्यवसाय (Education & Career), कौटुंबिक पार्श्वभूमी (Family Background), पत्रिका/ज्योतिष माहिती (Astrological Details), आणि अपेक्षा (Partner Expectations).\",\n            \"१. वैयक्तिक माहिती: पूर्ण नाव, जन्मतारीख, वेळ आणि जन्मठिकाण अचूक लिहा. उंची आणि वजन वास्तववादी असावे. रक्तगट आणि वर्ण नमूद केल्यास स्पष्टता राहते.\",\n            \"२. कुलदैवत व देवतेचे स्मरण: पारंपारिक बायोडाटा सुरू करताना '॥ श्री गणेशाय नमः ॥' किंवा आपल्या कुलदेवतेचे नाव आवर्जून वर मध्यभागी असावे.\",\n            \"३. पत्रिका माहिती: जर तुम्ही पत्रिका मानत असाल, तर राशी, नक्षत्र, चरण, गण, नाडी आणि मंगळ दोष (आहे/नाही) स्पष्टपणे नमूद करा. यामुळे पुढील संभाषण सोपे होते.\",\n            \"४. कौटुंबिक माहिती: आई-वडिलांचे पूर्ण नाव, त्यांचा व्यवसाय, भावंडे आणि मामांचे नाव व गाव अवश्य लिहावे. 'मामांचे आडनाव व गाव' हा महाराष्ट्रीयन परंपरेत महत्त्वाचा दुवा मानला जातो.\",\n            \"५. सुवाच्य आणि सुंदर फॉन्ट: गुंतागुंतीचा किंवा खूप लहान फॉन्ट वापरू नका. विवाहपत्रिका टूलच्या साहाय्याने तुम्ही काही मिनिटांत उच्च दर्जाचा आणि निर्दोष बायोडाटा तयार करू शकता.\"\n        ]\n    },\n    {\n        slug: \"top-10-marriage-biodata-mistakes\",\n        title: \"10 Common Mistakes People Make in Their Marriage Biodata (And How to Fix Them)\",\n        marathiTitle: \"विवाह बायोडाटा बनवताना होणाऱ्या १० सामान्य चुका आणि त्या कशा टाळाव्यात\",\n        excerpt: \"From outdated photos to ambiguous expectations, discover the subtle errors that cause profiles to get overlooked and how to fix them effortlessly.\",\n        category: \"Tips\",\n        date: \"2026-08-14\",\n        readTime: \"5 min read\",\n        author: \"Ananya Deshmukh\",\n        coverGradient: \"linear-gradient(135deg, #4A151C 0%, #800020 100%)\",\n        tags: [\n            \"Mistakes\",\n            \"Profile Tips\",\n            \"Matrimony Advice\"\n        ],\n        content: [\n            \"In the modern matchmaking process, your biodata is your primary representative before an actual conversation takes place. Even slight discrepancies or poorly styled documents can inadvertently create the wrong impression.\",\n            \"Mistake 1: Using Group Photos or Outdated Selfies. Always provide a clear, high-resolution portrait with good lighting and a natural, warm smile.\",\n            \"Mistake 2: Writing Vague Career Details. Instead of writing just 'Software Engineer', mention 'Senior Software Engineer at TCS, Pune (Package: 18 LPA)'. Transparency builds immediate trust.\",\n            \"Mistake 3: Overly Demanding or Negative Partner Expectations. Avoid writing statements like 'Don't contact if...'. Frame your desires positively, focusing on shared values, lifestyle alignment, and mutual respect.\",\n            \"Mistake 4: Typos and Inconsistent Marathi Spellings. Misspelled family surnames or gotra can be perceived as careless. Double check all names.\",\n            \"Mistake 5: Chaotic Formatting and Low Contrast. A cluttered document with microscopic fonts causes fatigue. Use clean typography with elegant spacing.\"\n        ]\n    },\n    {\n        slug: \"modern-vs-traditional-biodata-design\",\n        title: \"Modern vs. Traditional Biodata Designs: Which Style Suits Your Family Best?\",\n        marathiTitle: \"मॉडर्न विरुद्ध पारंपारिक बायोडाटा: तुमच्यासाठी कोणता योग्य आहे?\",\n        excerpt: \"Compare classic maroon-gold motifs with contemporary minimalist palettes to pick the visual style that honors tradition while highlighting individuality.\",\n        category: \"Design\",\n        date: \"2026-08-05\",\n        readTime: \"4 min read\",\n        author: \"Rohan Kothari\",\n        coverGradient: \"linear-gradient(135deg, #1B4D3E 0%, #B08A41 100%)\",\n        tags: [\n            \"Design Trends\",\n            \"Aesthetics\",\n            \"Templates\"\n        ],\n        content: [\n            \"The matrimonial landscape today is beautifully diverse. While some families deeply value heritage symbolism and ornate gold-foil borders, younger millennial and Gen-Z professionals often prefer editorial minimalism.\",\n            \"Traditional Styles: Feature rich auspicious colors such as crimson maroon, Paithani emerald, and turmeric gold. They give prominence to the deity header, horoscope details, gotra, and extensive family lineage.\",\n            \"Modern Styles: Utilize ivory tones, charcoal typography, and structured modular sections. They highlight career accomplishments, personal passions, global exposure, and lifestyle philosophies.\",\n            \"The Hybrid Approach: At विवाहपत्रिका, our templates like 'Royal Maroon' and 'Contemporary Beige' blend both worlds—offering sacred auspicious headers alongside modern clean layouts.\"\n        ]\n    },\n    {\n        slug: \"how-to-write-partner-expectations\",\n        title: \"The Art of Writing Dignified & Realistic Partner Expectations\",\n        marathiTitle: \"अपेक्षा (Partner Expectations) कशा लिहाव्यात? सन्माननीय आणि वास्तववादी दृष्टीकोन\",\n        excerpt: \"How to articulate your values, lifestyle preferences, and compatibility criteria without sounding restrictive or demanding.\",\n        category: \"Modern Matrimony\",\n        date: \"2026-07-28\",\n        readTime: \"6 min read\",\n        author: \"Pooja Kulkarni\",\n        coverGradient: \"linear-gradient(135deg, #9C4153 0%, #E7D6A7 100%)\",\n        tags: [\n            \"Partner Expectations\",\n            \"Matrimony\",\n            \"Values\"\n        ],\n        content: [\n            \"One of the most delicate sections of any marriage biodata is 'अपेक्षा' (Partner Expectations). It communicates your hopes for a life partner while reflecting your own personality and maturity.\",\n            \"1. Focus on core compatibility rather than endless superficial checklists. Highlight education, working preference, mutual understanding, and openness to progressive family values.\",\n            \"2. Be genuine about location preferences. If you work in Pune or abroad and need a partner willing to relocate, state this politely.\",\n            \"3. Respect individual freedom. Instead of rigid criteria, express openness to dialogue: 'Looking for an understanding, educated life companion with whom to build a supportive family together.'\"\n        ]\n    },\n    {\n        slug: \"importance-of-high-resolution-photo\",\n        title: \"Why a High-Quality Biodata Photo Can Make All the Difference\",\n        marathiTitle: \"बायोडाटामध्ये चांगल्या फोटोचे महत्त्व आणि फोटो कसा निवडावा?\",\n        excerpt: \"Practical tips on lighting, attire, posture, and framing to ensure your matrimonial portrait exudes warmth, confidence, and authenticity.\",\n        category: \"Tips\",\n        date: \"2026-07-15\",\n        readTime: \"4 min read\",\n        author: \"Vikram Jadhav\",\n        coverGradient: \"linear-gradient(135deg, #84301D 0%, #C5A059 100%)\",\n        tags: [\n            \"Photography\",\n            \"Portraits\",\n            \"First Impression\"\n        ],\n        content: [\n            \"A photograph speaks volumes before any words are read. When families review dozens of matrimonial profiles, an authentic, warm, and professional photograph stands out instantly.\",\n            \"Natural Lighting: Morning or late afternoon natural light works best. Avoid harsh camera flashes or dark ambient indoor lighting.\",\n            \"Attire: Choose neat ethnic or smart-casual wear that represents your authentic self without being overly ostentatious.\",\n            \"Framing: A medium close-up (chest-level to head) is ideal. Our built-in photo tool lets you effortlessly crop, rotate, and center your picture inside your chosen biodata template.\"\n        ]\n    },\n    {\n        slug: \"astrology-and-horoscope-in-biodata\",\n        title: \"Demystifying Horoscope & Kundali Details in Indian Biodatas\",\n        marathiTitle: \"बायोडाटामध्ये पत्रिका आणि कुंडलीची अचूक माहिती कशी भरावी?\",\n        excerpt: \"Understanding Rashi, Nakshatra, Gan, Nadi, and Manglik status—and why accurate details save time for astrological matching.\",\n        category: \"Family\",\n        date: \"2026-07-02\",\n        readTime: \"7 min read\",\n        author: \"पं. माधवशास्त्री जोशी\",\n        coverGradient: \"linear-gradient(135deg, #781D10 0%, #4D391A 100%)\",\n        tags: [\n            \"कुंडली\",\n            \"राशी\",\n            \"नक्षत्र\",\n            \"मंगळ दोष\",\n            \"Astrology\"\n        ],\n        content: [\n            \"भारतीय विवाह व्यवस्थेत पत्रिकामिलन (Horoscope Matching) हा अनेक कुटुंबांसाठी एक महत्त्वाचा टप्पा असतो. गुणमेलन (Gun Milan) करताना योग्य माहिती उपलब्ध नसल्यास गैरसमज होऊ शकतात.\",\n            \"बायोडाटात नमूद करावयाची महत्त्वाची कुंडली सूत्रे: जन्मदिनांक, अचूक जन्मवेळ (सकाळ/दुपार/रात्र स्पष्ट नमूद करावी), जन्मस्थान, जन्मराशी, जन्मनक्षत्र व चरण, गण (देव/मनुष्य/राक्षस), आणि नाडी (आद्य/मध्य/अंत्य).\",\n            \"मंगळ दोषाबद्दल स्पष्टता: जर कुंडलीत मंगळ असेल किंवा सौम्य/आंशिक असेल तर ते थेट नमूद करणे हितावह ठरते. यामुळे दोन्ही कुटुंबांचा वेळ वाचतो.\"\n        ]\n    },\n    {\n        slug: \"digital-biodata-vs-printed-patrika\",\n        title: \"Digital WhatsApp Biodatas vs Printed Biodatas: Best Practices for Both\",\n        marathiTitle: \"व्हॉट्सॲप डिजिटल बायोडाटा आणि प्रिंटेड पत्रिका: दोन्हीचे योग्य वापर\",\n        excerpt: \"How to format your document for crisp mobile sharing on WhatsApp while ensuring it prints flawlessly on standard A4 paper.\",\n        category: \"Marriage Biodata\",\n        date: \"2026-06-21\",\n        readTime: \"5 min read\",\n        author: \"Shubham Kadam\",\n        coverGradient: \"linear-gradient(135deg, #1B2A4A 0%, #94A3B8 100%)\",\n        tags: [\n            \"WhatsApp Sharing\",\n            \"PDF\",\n            \"Printable\",\n            \"Digital\"\n        ],\n        content: [\n            \"In earlier decades, biodatas were physically printed and posted or handed over during formal visits. Today, 95% of matrimonial first contacts occur over WhatsApp, email, or matrimonial apps.\",\n            \"For WhatsApp: You need a sharp, high-resolution image (JPG/PNG) or lightweight PDF that opens instantly on mobile phones without pixelation or zooming issues.\",\n            \"For Family Meetings: Having 2-3 crisp physical color printouts on good bond paper when visiting the prospective bride or groom's home shows courtesy and seriousness.\",\n            \"VivahPatrika allows you to generate both: high-resolution mobile images and vector-crisp printable A4 PDFs.\"\n        ]\n    },\n    {\n        slug: \"family-introduction-etiquette\",\n        title: \"How to Describe Your Family Background with Dignity & Warmth\",\n        marathiTitle: \"कौटुंबिक पार्श्वभूमी लिहिताना कोणती काळजी घ्यावी?\",\n        excerpt: \"Proper terminology for describing parents, extended relatives, ancestral roots, and family values in modern Marathi matrimony.\",\n        category: \"Family\",\n        date: \"2026-06-10\",\n        readTime: \"5 min read\",\n        author: \"Sunita Gokhale\",\n        coverGradient: \"linear-gradient(135deg, #5D1E26 0%, #B08A41 100%)\",\n        tags: [\n            \"Family Culture\",\n            \"Etiquette\",\n            \"Marathi Tradition\"\n        ],\n        content: [\n            \"A marriage unites two family trees. When elders read a biodata, the 'कौटुंबिक माहिती' (Family Details) section is often scrutinized with greatest care.\",\n            \"1. Mentioning Parents: Write father's and mother's names with respectful salutations (श्री. / सौ. / कै. if deceased). Mention their profession or retirement status clearly.\",\n            \"2. Siblings: Mention whether siblings are married or studying, along with their professions.\",\n            \"3. Ancestral Roots (मूळ गाव / Native Place): In Maharashtra, native place roots provide cultural context and community connectivity.\",\n            \"4. Maternal Relatives (मामांचे कुल): Respectfully mention maternal uncle's name and city. It reflects openness and strong family bonding.\"\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./data/blogs.ts\n");

